param([int]$Days=30)
. (Join-Path $PSScriptRoot "Common.ps1")
$codexHome=Get-CodexHome;$factory=Get-FactoryHome;$cut=(Get-Date).Date.AddDays(-([Math]::Max($Days,1)-1));$files=@()
try{$files=Get-ChildItem -LiteralPath $codexHome -Recurse -Filter *.jsonl -File -ErrorAction SilentlyContinue|Where-Object{$_.FullName -notlike "$factory*"}}catch{}
$sum=[ordered]@{calls=0;sessions=@{};total=0L;input=0L;cached=0L;output=0L;reasoning=0L};$seen=@{}
foreach($f in $files){try{foreach($line in [IO.File]::ReadLines($f.FullName)){if($line.IndexOf('"token_count"') -lt 0){continue};try{$o=$line|ConvertFrom-Json}catch{continue};if($o.payload.type -ne "token_count" -or !$o.payload.info.last_token_usage){continue};try{$dt=[DateTimeOffset]::Parse($o.timestamp).LocalDateTime}catch{continue};if($dt.Date -lt $cut){continue};$u=$o.payload.info.last_token_usage;$k="$($f.FullName)|$($o.timestamp)|$($u.total_tokens)|$($u.input_tokens)|$($u.output_tokens)";if($seen[$k]){continue};$seen[$k]=$true;$sum.calls++;$sum.sessions[$f.FullName]=$true;$sum.total+=[int64]$u.total_tokens;$sum.input+=[int64]$u.input_tokens;$sum.cached+=[int64]$u.cached_input_tokens;$sum.output+=[int64]$u.output_tokens;$sum.reasoning+=[int64]$u.reasoning_output_tokens}}catch{}}
$non=$sum.input-$sum.cached;$net=$non+$sum.output;$rate=if($sum.input){100.0*$sum.cached/$sum.input}else{0}
Write-Host "Codex usage - last $Days days";Write-Host ("Sessions: {0} | events: {1}" -f $sum.sessions.Count,$sum.calls);Write-Host ("Total: {0:N0}" -f $sum.total);Write-Host ("Input: {0:N0} | cached: {1:N0} | non-cached: {2:N0}" -f $sum.input,$sum.cached,$non);Write-Host ("Output: {0:N0} | reasoning: {1:N0}" -f $sum.output,$sum.reasoning);Write-Host ("Net*: {0:N0} | cache hit: {1:N2}%" -f $net,$rate);Write-Host "* Net = non-cached input + output"
